#!/usr/bin/env python3
"""Generate test/fixtures/Ks256LowSVectors.sol from the shared KS256 low-s
vector.

Source of truth: protocol/vectors/fixtures/ks256-low-s.json (vendored,
unchanged, at test/fixtures/ks256-low-s.json; cases described in
protocol/vectors/README.md, "KS256 low-s"). This script never edits a
vector; it only reads the vendored JSON and prints a Solidity library.

Foundry's fs_permissions does not include test/, so the vector is baked
into Solidity source at generation time rather than read at test time
(same approach as gen_kat39_vectors.py).

Usage:
    python3 test/fixtures/gen_ks256_low_s_vectors.py \
        > test/fixtures/Ks256LowSVectors.sol
"""

import hashlib
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
VECTOR_PATH = HERE / "ks256-low-s.json"


def checksum_address(hex40: str) -> str:
    """EIP-55 checksum, which solc requires of address literals."""
    lower = hex40.lower()
    digest = keccak256(lower.encode()).hex()
    return "0x" + "".join(
        c.upper() if c.isalpha() and int(digest[i], 16) >= 8 else c
        for i, c in enumerate(lower)
    )


# Keccak-256 (the pre-NIST padding Ethereum uses); hashlib's sha3_256 is
# the NIST variant and gives different digests.
_RC = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808A,
    0x8000000080008000, 0x000000000000808B, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008A,
    0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
    0x000000008000808B, 0x800000000000008B, 0x8000000000008089,
    0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
    0x000000000000800A, 0x800000008000000A, 0x8000000080008081,
    0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
]
_ROT = [
    [0, 36, 3, 41, 18], [1, 44, 10, 45, 2], [62, 6, 43, 15, 61],
    [28, 55, 25, 21, 56], [27, 20, 39, 8, 14],
]
_M = (1 << 64) - 1


def _rol(v: int, n: int) -> int:
    return ((v << n) | (v >> (64 - n))) & _M if n else v


def _keccak_f(a):
    for rc in _RC:
        c = [a[x][0] ^ a[x][1] ^ a[x][2] ^ a[x][3] ^ a[x][4] for x in range(5)]
        d = [c[(x - 1) % 5] ^ _rol(c[(x + 1) % 5], 1) for x in range(5)]
        a = [[a[x][y] ^ d[x] for y in range(5)] for x in range(5)]
        b = [[0] * 5 for _ in range(5)]
        for x in range(5):
            for y in range(5):
                b[y][(2 * x + 3 * y) % 5] = _rol(a[x][y], _ROT[x][y])
        a = [
            [b[x][y] ^ (~b[(x + 1) % 5][y] & b[(x + 2) % 5][y]) for y in range(5)]
            for x in range(5)
        ]
        a[0][0] ^= rc
    return a


def keccak256(data: bytes) -> bytes:
    rate = 136
    msg = bytearray(data) + b"\x01"
    while len(msg) % rate:
        msg.append(0)
    msg[-1] |= 0x80
    a = [[0] * 5 for _ in range(5)]
    for off in range(0, len(msg), rate):
        block = msg[off:off + rate]
        for i in range(rate // 8):
            x, y = i % 5, i // 5
            a[x][y] ^= int.from_bytes(block[8 * i:8 * i + 8], "little")
        a = _keccak_f(a)
    out = b""
    for i in range(4):
        out += a[i % 5][i // 5].to_bytes(8, "little")
    return out


def main() -> None:
    raw = VECTOR_PATH.read_bytes()
    v = json.loads(raw)
    sha = hashlib.sha256(raw).hexdigest()
    out = []
    out.append("// SPDX-License-Identifier: Apache-2.0")
    out.append("pragma solidity ^0.8.24;")
    out.append("")
    out.append("// GENERATED FILE. DO NOT EDIT BY HAND.")
    out.append("// Generated by test/fixtures/gen_ks256_low_s_vectors.py from the")
    out.append("// vendored shared KS256 low-s vector:")
    out.append("//   test/fixtures/ks256-low-s.json")
    out.append(f"// source sha256: {sha}")
    out.append("// Upstream: protocol/vectors/fixtures/ks256-low-s.json,")
    out.append("// protocol/vectors/README.md (\"KS256 low-s\"). Regenerate with:")
    out.append("//   python3 test/fixtures/gen_ks256_low_s_vectors.py \\")
    out.append("//     > test/fixtures/Ks256LowSVectors.sol")
    out.append("")
    out.append("/// @notice Baked-in KS256 low-s vector. Every value here is copied")
    out.append("///    unchanged from the pinned JSON; a value this generator cannot")
    out.append("///    reproduce is a generator bug, never a reason to hand-edit it.")
    out.append("library Ks256LowSVectors {")
    out.append("    struct Case {")
    out.append("        string name;")
    out.append("        address signer;")
    out.append("        bytes signature; // 65 bytes r || s || v, v the recovery id 0 or 1")
    out.append("        bool accept;")
    out.append("    }")
    out.append("")
    out.append(f"    int64 internal constant ALG = {v['alg']};")
    out.append(
        "    uint256 internal constant LOW_S_BOUND =\n"
        f"        0x{v['conventions']['low_s_bound']};"
    )
    out.append(
        "    bytes32 internal constant DIGEST =\n"
        f"        hex\"{v['digest_hex']}\";"
    )
    out.append("")
    for fn, key in (
        ("protectedHeader", "protected_header_hex"),
        ("payload", "payload_hex"),
        ("sigStructure", "sig_structure_hex"),
    ):
        out.append(f"    function {fn}() internal pure returns (bytes memory) {{")
        out.append(f"        return hex\"{v[key]}\";")
        out.append("    }")
        out.append("")
    cases = v["cases"]
    out.append("    function cases() internal pure returns (Case[] memory c) {")
    out.append(f"        c = new Case[]({len(cases)});")
    for i, case in enumerate(cases):
        accept = "true" if case["expect"]["result"] == "accept" else "false"
        out.append(f"        c[{i}] = Case({{")
        out.append(f"            name: \"{case['name']}\",")
        out.append(f"            signer: {checksum_address(case['signer_address_hex'])},")
        out.append(f"            signature: hex\"{case['signature_hex']}\",")
        out.append(f"            accept: {accept}")
        out.append("        });")
    out.append("    }")
    out.append("}")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
